import 'fake-indexeddb/auto';
import {it,expect,afterEach} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {createEntity,newId} from '../src/domain/model';
import type {ProjectData} from '../src/domain/types';
import type {PublicProjection} from '../src/domain/projection';
import {ScenarioStore} from '../src/storage/store';
import {assetPath} from '../src/storage/archive';
import {jsonBytes,sha256} from '../src/storage/json';
import {inspectConfirmedArchive,encodeSyncBytes} from '../src/sync/archiveTransfer';
import {nativeDocuments} from '../src/sync/nativeBridge';
import {valueHash} from '../src/sync/protocol';
import {validateSharedSnapshot,projectedRichText,type SharedSnapshot} from '../src/sync/publicShare';
const root='/tmp/shinariokanri-independent-rb09-ff971b7/independent',stores:ScenarioStore[]=[];
function store(accountId='00000000-0000-4000-8000-000000000001'){const s=new ScenarioStore({databaseName:`independent-rb09-transfer-${newId()}`,accountId});stores.push(s);return s;}
afterEach(async()=>{for(const s of stores.splice(0))await s.deleteDatabase();});
function proof(id:string,value:unknown){writeFileSync(`${root}/fixtures/${id}.json`,JSON.stringify(value,null,2)+'\n');}
async function fullArchive(){const input=JSON.parse(readFileSync(`${root}/fixtures/native-two-targets.json`,'utf8')) as {p:ProjectData},p=structuredClone(input.p);p.name='独立 完全復元対象😀';p.projectId=newId();for(const e of p.entities)e.projectId=p.projectId;const bytes=new TextEncoder().encode('素材bytesを空環境へ😀'),hash=await sha256(bytes),attachment=createEntity(p.projectId,'attachment','資料の原ファイル名秘密canary',{mediaType:'text/plain',contentHash:hash,byteSize:bytes.length,assetPath:assetPath(hash,'text/plain'),displayName:'端末元ファイル秘密canary.txt',stage:'final'});attachment.status='confirmed';attachment.visibility='private';p.entities.push(attachment);const s=store(),saved=await s.saveProject(p,{reason:'独立 原子完全保存と素材',assets:[{contentHash:hash,bytes,mediaType:'text/plain'}]}),documents=nativeDocuments(saved.project,'1'),contentHash=await valueHash(documents);await s.bindConfirmedProject({projectId:p.projectId,serverRevision:'1',documents,contentHash,localRevision:saved.project.revision,outboxIds:(await s.listOutbox(p.projectId)).map(o=>o.operationId)});const archive=await s.exportProject(p.projectId);writeFileSync(`${root}/fixtures/remote-complete.scenario`,archive);proof('remote-native',{project:saved.project,documents,contentHash,serverRevision:'1',worlds:{},assetHash:hash,assetBytes:[...bytes]});return {source:s,project:saved.project,documents,contentHash,archive,hash,bytes};}
it('R9TV01 confirmed complete archive restores to empty account cache with canonical edition and actual attachment bytes, then cold rereads',async()=>{const f=await fullArchive(),prepared=await inspectConfirmedArchive(f.archive,f.project.projectId,f.documents),target=store(),result=await target.importScenario(prepared,{mode:'new'});await target.bindConfirmedProject({projectId:f.project.projectId,serverRevision:'1',documents:f.documents,contentHash:f.contentHash,localRevision:result.project.revision,outboxIds:(await target.listOutbox(f.project.projectId)).map(o=>o.operationId)});expect(await target.getAsset(f.hash)).toEqual(f.bytes);expect((await target.getProject(f.project.projectId))?.entities.map(e=>e.id)).toEqual(f.project.entities.map(e=>e.id));const base=await target.getConfirmedSyncBase(f.project.projectId);expect(base?.contentHash).toBe(f.contentHash);target.close();const cold=new ScenarioStore({databaseName:(target as unknown as {db:{name:string}}).db.name,accountId:target.accountId!});stores.push(cold);expect(await cold.getAsset(f.hash)).toEqual(f.bytes);expect((await cold.getConfirmedSyncBase(f.project.projectId))?.serverRevision).toBe('1');proof('R9TV01',{projectId:result.project.projectId,assetHash:f.hash,actualBytes:[...(await cold.getAsset(f.hash))!],base});});
it('R9TV02 complete archive clone maps owned IDs while keeping bytes and explicit needs_reconnect recovery rather than falsely synced',async()=>{const f=await fullArchive(),prepared=await inspectConfirmedArchive(f.archive,f.project.projectId,f.documents),target=store(),result=await target.importScenario(prepared,{mode:'clone'});expect(result.project.projectId).not.toBe(f.project.projectId);expect(result.project.entities.every(e=>e.projectId===result.project.projectId&&!f.project.entities.some(old=>old.id===e.id))).toBe(true);expect(await target.getAsset(f.hash)).toEqual(f.bytes);expect(await target.getConfirmedSyncBase(result.project.projectId)).toBeUndefined();proof('R9TV02',{sourceProjectId:f.project.projectId,cloneProject:result.project,idMap:result.idMap,saveState:await target.getSaveState(result.project.projectId)});});
it('R9TV03 wrong confirmed content and canceled complete-archive inspection preserve existing local content, history, and bytes',async()=>{const f=await fullArchive(),before=await f.source.getProject(f.project.projectId),beforeHistory=await f.source.listHistory(f.project.projectId),wrong=structuredClone(f.documents);wrong.find(d=>d.fields.kind==='note')!.fields.name='別のサーバー版';await expect(inspectConfirmedArchive(f.archive,f.project.projectId,wrong)).rejects.toMatchObject({code:'REVISION_CHANGED'});const abort=new AbortController();abort.abort();await expect(inspectConfirmedArchive(f.archive,f.project.projectId,f.documents,abort.signal)).rejects.toThrow();await expect(encodeSyncBytes(new Uint8Array(200000),abort.signal)).rejects.toMatchObject({code:'CANCELLED'});expect(await f.source.getProject(f.project.projectId)).toEqual(before);expect(await f.source.listHistory(f.project.projectId)).toEqual(beforeHistory);expect(await f.source.getAsset(f.hash)).toEqual(f.bytes);proof('R9TV03',{projectId:f.project.projectId,unchanged:true,negative:['wrong confirmed content','cancel before inspect','cancel before byte encoding']});});
async function shared(){const old:PublicProjection={format:'scenario-projection',formatVersion:'1.0.0',title:'旧公開本文の固定版😀',calendars:[],entities:[{id:'public-target',kind:'note',name:'旧対象だけ',status:'confirmed',data:{body:[{id:'old-public-block',kind:'paragraph',text:'A😀古い参照先'}],attachmentIds:[]}}],relations:[],searchIndex:[{entityId:'public-target',kind:'note',name:'旧対象だけ',text:'A😀古い参照先',normalized:'A😀古い参照先'}]},projection:PublicProjection={format:'scenario-projection',formatVersion:'1.0.0',title:'独立 限定公開版😀',calendars:[],entities:[{id:'public-source',kind:'note',name:'公開元',status:'confirmed',data:{body:[{id:'public-block-source',kind:'paragraph',text:'😀戻る読み位置',links:[{start:0,end:1,targetId:'public-target',blockId:'old-public-block',sourceVersionId:'public-edition-old',targetStart:1,targetEnd:2}]}],attachmentIds:[]}}],relations:[],searchIndex:[{entityId:'public-source',kind:'note',name:'公開元',text:'😀戻る読み位置',normalized:'😀戻る読み位置'}],versions:[{id:'public-edition-old',projection:old}]},input:SharedSnapshot={id:'40000000-0000-4000-8000-000000000005',projection,contentHash:await sha256(jsonBytes(projection)),createdAt:'2026-10-08T17:00:00.000Z',accessExpiresAt:null,role:'reviewer'};return input;}
it('R9TV04 validated limited projection retains fixed edition and Unicode target offsets without private names or author IDs',async()=>{const input=await shared(),valid=await validateSharedSnapshot(input),blocks=projectedRichText(valid.projection.entities[0].data.body);expect(blocks[0].links![0].target).toEqual({entityId:'public-target',blockId:'old-public-block',sourceVersionId:'public-edition-old',start:1,end:2});expect(JSON.stringify(valid)).not.toContain('秘密canary');proof('shared-snapshot',valid);});
it('R9TV05 modified limited projection hash and unknown fixed Unicode target reject instead of silently replacing the edition',async()=>{const input=await shared(),wrong=structuredClone(input);wrong.projection.title='差替本文';await expect(validateSharedSnapshot(wrong)).rejects.toMatchObject({code:'PROTOCOL_INVALID'});const unknown=structuredClone(input),body=unknown.projection.entities[0].data.body as unknown as {links:{sourceVersionId:string}[]}[];body[0].links[0].sourceVersionId='public-missing-edition';unknown.contentHash=await sha256(jsonBytes(unknown.projection));await expect(validateSharedSnapshot(unknown)).rejects.toMatchObject({code:'PROTOCOL_INVALID'});proof('R9TV05',{wrongHashRejected:true,unknownEditionRejected:true});});
